def extract_and_visualize_json(
    json_obj: Any,
    path: Union[str, List[Union[str, int]]],
    plot_type: str = "hist",           # 'hist', 'line', or 'scatter'
    bins: int = 30,                    # used for histogram
    title: str = None,
    x_label: str = None,
    y_label: str = None,
    show: bool = True,
    save_path: str = None              # optional file path to save static image (requires orca/ Kaleido)
) -> Dict[str, Any]:
    """
    Extract numeric values from json_obj following the specified path, then visualize with Plotly.

    Parameters:
    - json_obj: Python structure parsed from JSON (dicts/lists/values).
    - path: Either a list of keys/indices or a single string with components separated by '/'.
            Special token '*' acts as a wildcard to iterate all values/items at that level.
            Example paths: ['top','items','*','value'] or "top/items/*/value" or ["data", 0, "score"]
    - plot_type: 'hist', 'line', or 'scatter'
    - bins: number of bins for histogram
    - title, x_label, y_label: labels for the plot
    - show: if True, call fig.show()
    - save_path: if provided, call fig.write_image(save_path) (requires Kaleido installed)

    Returns: dict with keys:
      - 'values': list of extracted numeric values
      - 'fig': Plotly Figure object (may be None if no values)
    """

    # Normalize path into list of tokens
    if isinstance(path, str):
        # allow leading/trailing slashes; empty segments ignored
        tokens: List[Union[str,int]] = [tok for tok in path.split("/") if tok != ""]
    else:
        tokens = list(path)

    # Convert tokens that are integer-looking strings into ints
    def normalize_token(tok):
        if isinstance(tok, str):
            if tok == "*":
                return "*"
            # try to parse integer index
            try:
                return int(tok)
            except Exception:
                return tok
        return tok

    tokens = [normalize_token(t) for t in tokens]

    # Helper: recursively gather numbers from a node (when path exhausted)
    collected: List[float] = []
    def gather_numbers(node: Any):
        if isinstance(node, bool):
            # exclude booleans (subclass of int)
            return
        if isinstance(node, numbers.Number):
            collected.append(float(node))
            return
        if isinstance(node, dict):
            for v in node.values():
                gather_numbers(v)
            return
        if isinstance(node, (list, tuple)):
            for item in node:
                gather_numbers(item)
            return
        # otherwise ignore non-numeric leaf

    # Helper: follow path tokens over current nodes
    def follow_path(nodes: List[Any], idx: int):
        if idx >= len(tokens):
            # path exhausted: gather numeric values under each node
            for n in nodes:
                gather_numbers(n)
            return

        token = tokens[idx]
        next_nodes: List[Any] = []

        for n in nodes:
            if token == "*":
                if isinstance(n, dict):
                    next_nodes.extend(n.values())
                elif isinstance(n, (list, tuple)):
                    next_nodes.extend(n)
                else:
                    # wildcard at a non-iterable node produces nothing
                    continue
            elif isinstance(token, int):
                if isinstance(n, (list, tuple)):
                    # allow negative indices too
                    try:
                        next_nodes.append(n[token])
                    except Exception:
                        continue
                else:
                    continue
            else:
                # string key
                if isinstance(n, dict) and token in n:
                    next_nodes.append(n[token])
                else:
                    continue

        if not next_nodes:
            # No nodes to continue; end early
            return
        follow_path(next_nodes, idx + 1)

    # Start traversal
    follow_path([json_obj], 0)

    # Build plot if we have values
    fig = None
    if not collected:
        return {"values": [], "fig": None}

    # Labels defaults
    if title is None:
        title = f"Extracted numeric values ({len(collected)})"
    if x_label is None:
        x_label = "index" if plot_type in ("line", "scatter") else "value"
    if y_label is None:
        y_label = "value" if plot_type in ("line", "scatter") else "count"

    if plot_type == "hist":
        fig = px.histogram(collected, nbins=bins, title=title, labels={"value": x_label, "count": y_label})
    elif plot_type == "line":
        fig = px.line(y=collected, title=title, labels={"index": x_label, "y": y_label})
    elif plot_type == "scatter":
        fig = px.scatter(x=list(range(len(collected))), y=collected, title=title, labels={"x": x_label, "y": y_label})
