                # Count leap second if it lies strictly after start and <= now.
                # This policy counts leap seconds that became effective during the open-closed interval (start, now].
                if start < t <= now:
                    count += 1
            leap_count = count

    if leap_count is None:
        raise RuntimeError(
            "Could not determine leap seconds from the 'leapseconds' library: "
            "expected an API like count(start,end), between(start,end), or leap_seconds()/list()."
        )

    # Total elapsed seconds including leap seconds. Keep fractional part from elapsed.
    total_seconds_including_leaps = float(elapsed) + float(leap_count)
    return total_seconds_including_leaps

