import re
import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse, urlunparse

URL_RE = re.compile(
    r'(?P<url>(https?://[^\s<>"\'()]+|www\.[^\s<>"\'()]+))',
    flags=re.IGNORECASE
)

def _normalize_url(raw_url: str) -> str:
    # Add http:// if missing scheme
    if raw_url.startswith('www.'):
        raw_url = 'http://' + raw_url
    parsed = urlparse(raw_url, allow_fragments=True)
    # If no netloc but path looks like domain (rare), return as-is
    if not parsed.scheme:
        parsed = parsed._replace(scheme='http')
    # Rebuild to ensure consistent formatting
    return urlunparse(parsed)

def fetch_title_from_text(text: str, timeout: float = 10.0) -> dict:
    """
    Extract the first URL from `text` and fetch its page title.

    Returns:
      {'ok': True, 'title': '<title string>'} on success
      {'ok': False, 'error': '<error message>'} on failure
    """
    if not text or not isinstance(text, str):
        return {'ok': False, 'error': 'Input must be a non-empty string.'}

    m = URL_RE.search(text)
    if not m:
        return {'ok': False, 'error': 'No URL found in input text.'}

    raw_url = m.group('url').rstrip('.,;:!?)"\']')  # trim common trailing punctuation
    url = _normalize_url(raw_url)

    headers = {
        'User-Agent': 'Mozilla/5.0 (compatible; TitleFetcher/1.0; +https://example.com/bot)'
    }

    try:
        resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return {'ok': False, 'error': f'Network error when fetching URL: {e}'}

    if resp.status_code < 200 or resp.status_code >= 300:
        return {'ok': False, 'error': f'URL returned HTTP status {resp.status_code}.'}

    content_type = resp.headers.get('Content-Type', '')
    if 'html' not in content_type.lower():
        return {'ok': False, 'error': f'URL did not return HTML (Content-Type: {content_type}).'}

    # Parse HTML and extract title
    try:
        soup = BeautifulSoup(resp.text, 'html.parser')
    except Exception as e:
        return {'ok': False, 'error': f'Failed to parse HTML: {e}'}

    # Order of preference: og:title, twitter:title, <title>, first <h1>
    title = None
    og = soup.find('meta', property='og:title')
    if og and og.get('content'):
        title = og['content'].strip()
    if not title:
        tw = soup.find('meta', attrs={'name': 'twitter:title'})
        if tw and tw.get('content'):
            title = tw['content'].strip()
    if not title and soup.title and soup.title.string:
        title = soup.title.string.strip()
    if not title:
        h1 = soup.find('h1')
        if h1 and h1.get_text(strip=True):
            title = h1.get_text(strip=True)

    if title:
        return {'ok': True, 'title': title}
    else:
        return {'ok': False, 'error': 'No title found in HTML.'}

